package com.primehr.rewardsrecognition.application;

import com.primehr.integration.administrative.PermissionDataScope;
import com.primehr.rewardsrecognition.api.RrAwardDtos.*;
import com.primehr.rewardsrecognition.domain.*;
import com.primehr.rewardsrecognition.infrastructure.*;
import com.primehr.shared.audit.PrimeHrAuditService;
import com.primehr.shared.exception.*;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.*;
import java.util.*;

@Service @Transactional
public class RrAwardServiceImpl implements RrAwardService {
 private final RrAwardRecordRepository awards; private final RrIncentiveAuthorizationRepository incentives;
 private final RrFulfillmentEventRepository fulfillment; private final RrHapEndorsementEventRepository hap;
 private final RrEvaluationCaseRepository cases; private final RrEvaluatorAssignmentRepository assignments;
 private final RrNominationRepository nominations; private final RrNominationMemberRepository members;
 private final RrAwardCycleRepository cycles; private final RrAwardCategoryVersionRepository categories;
 private final PrimeHrAuditService audit;
 public RrAwardServiceImpl(RrAwardRecordRepository awards,RrIncentiveAuthorizationRepository incentives,
   RrFulfillmentEventRepository fulfillment,RrHapEndorsementEventRepository hap,RrEvaluationCaseRepository cases,
   RrEvaluatorAssignmentRepository assignments,RrNominationRepository nominations,RrNominationMemberRepository members,
   RrAwardCycleRepository cycles,RrAwardCategoryVersionRepository categories,PrimeHrAuditService audit){
  this.awards=awards;this.incentives=incentives;this.fulfillment=fulfillment;this.hap=hap;this.cases=cases;
  this.assignments=assignments;this.nominations=nominations;this.members=members;this.cycles=cycles;
  this.categories=categories;this.audit=audit;
 }
 @Override @Transactional(readOnly=true) public List<AwardResponse> awards(String a,String actor,PermissionDataScope scope){return awards.findByAgencyIdOrderByAuthorizedAtDesc(a).stream().filter(x->current(a,x)&&visible(a,x,actor,scope)).map(x->response(a,x)).toList();}
 @Override @Transactional(readOnly=true) public AwardResponse get(String a,String id,String actor,PermissionDataScope scope){var x=award(a,id);if(!visible(a,x,actor,scope))throw new AccessDeniedException("Award record is outside the permitted scope");return response(a,x);}
 @Override public AwardResponse confer(String a,String caseId,ConferInput in,String actor,String c){
  var evaluation=cases.findByIdAndAgencyId(caseId,a).orElseThrow(()->new ResourceNotFoundException("Evaluation case not found"));
  if(evaluation.getStatus()!=RrEvaluationCase.Status.FINAL_APPROVED)throw new IllegalStateException("Only a final approved decision may be conferred");
  if(awards.findByAgencyIdAndEvaluationCaseIdAndRecordType(a,caseId,RrAwardRecord.RecordType.CONFERMENT).isPresent())throw new OptimisticConflictException("An award has already been conferred for this decision");
  var nomination=nominations.findByIdAndAgencyId(evaluation.getNominationId(),a).orElseThrow(()->new ResourceNotFoundException("Nomination not found"));
  var cycle=cycles.findByIdAndAgencyId(evaluation.getCycleId(),a).orElseThrow(()->new ResourceNotFoundException("Award cycle not found"));
  if(cycle.getConfermentOn()!=null&&!cycle.getConfermentOn().equals(in.conferredOn()))throw new IllegalArgumentException("Conferment date must match the frozen award cycle");
  if(in.conferredOn().isBefore(cycle.getDecisionDueOn()))throw new IllegalArgumentException("Conferment cannot precede the decision due date");
  var category=categories.findByIdAndAgencyId(evaluation.getCategoryVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Award category not found"));
  String code="RR-"+in.conferredOn().getYear()+"-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(Locale.ROOT);
  String nominee=nominee(a,nomination);String fp=fingerprint(caseId,nomination.getSubmissionFingerprint(),category.getId(),in.certificateTitle(),in.publicationCitation(),in.conferredOn().toString());
  var value=awards.saveAndFlush(RrAwardRecord.confer(a,caseId,nomination.getId(),cycle.getId(),category.getId(),code,nomination.getNomineeType().name(),nominee,category.getTitle(),in.certificateTitle(),in.publicationCitation(),in.conferredOn(),in.reason(),actor,Instant.now(),fp));
  record(a,"CONFER_RR_AWARD",value,null,response(a,value),in.reason(),c);return response(a,value);
 }
 @Override public AwardResponse correct(String a,String id,CorrectInput in,String actor,String c){var source=leaf(a,id);check(source.getVersion(),in.recordVersion());validateConferment(a,source.getCycleId(),in.conferredOn());var value=awards.saveAndFlush(source.correct(in.certificateTitle(),in.publicationCitation(),in.conferredOn(),in.reason(),actor,Instant.now(),fingerprint(source.getSourceFingerprint(),in.certificateTitle(),in.publicationCitation(),in.conferredOn().toString(),in.reason())));record(a,"CORRECT_RR_AWARD",value,response(a,source),response(a,value),in.reason(),c);return response(a,value);}
 @Override public AwardResponse revoke(String a,String id,RevokeInput in,String actor,String c){var source=leaf(a,id);check(source.getVersion(),in.recordVersion());var value=awards.saveAndFlush(source.revoke(in.reason(),actor,Instant.now(),fingerprint(source.getSourceFingerprint(),"REVOCATION",in.reason())));record(a,"REVOKE_RR_AWARD",value,response(a,source),response(a,value),in.reason(),c);return response(a,value);}
 @Override public AwardResponse authorizeIncentive(String a,String id,IncentiveInput in,String actor,PermissionDataScope scope,String c){
  var award=leaf(a,id);access(a,award,actor,scope);active(award);var category=categories.findByIdAndAgencyId(award.getCategoryVersionId(),a).orElseThrow(()->new ResourceNotFoundException("Award category not found"));
  if(category.getIncentiveType()==RrAwardCategoryVersion.IncentiveType.MONETARY&&in.type()!=RrIncentiveAuthorization.Type.MONETARY||category.getIncentiveType()==RrAwardCategoryVersion.IncentiveType.NON_MONETARY&&in.type()!=RrIncentiveAuthorization.Type.NON_MONETARY)throw new IllegalArgumentException("Incentive type is not allowed by the frozen award category");
  var value=incentives.saveAndFlush(new RrIncentiveAuthorization(a,award.getId(),in.type(),in.description(),in.authorizedAmount(),in.currencyCode(),in.authorizationReference(),actor,Instant.now()));record(a,"AUTHORIZE_RR_INCENTIVE",value,null,incentiveResponse(a,value),in.authorizationReference(),c);return response(a,award);
 }
 @Override public AwardResponse recordFulfillment(String a,String awardId,String authorizationId,FulfillmentInput in,String actor,PermissionDataScope scope,String c){
  var requested=award(a,awardId);var current=currentAward(a,requested.getRootAwardId());access(a,current,actor,scope);active(current);var authorization=incentives.findByIdAndAgencyId(authorizationId,a).orElseThrow(()->new ResourceNotFoundException("Incentive authorization not found"));
  if(!lineage(a,requested.getRootAwardId()).stream().map(RrAwardRecord::getId).anyMatch(authorization.getAwardRecordId()::equals))throw new ResourceNotFoundException("Incentive authorization not found");
  var history=fulfillment.findByAgencyIdAndAuthorizationIdOrderByRecordedAt(a,authorizationId);if(!history.isEmpty()){var last=history.get(history.size()-1);if(last.getStatus()==RrFulfillmentEvent.Status.FULFILLED||last.getStatus()==RrFulfillmentEvent.Status.CANCELLED)throw new IllegalStateException("Fulfillment ledger is already final");}
  BigDecimal amount=in.fulfilledAmount();if(in.status()==RrFulfillmentEvent.Status.CANCELLED){if(amount!=null)throw new IllegalArgumentException("Cancelled fulfillment cannot contain an amount");}else if(authorization.getIncentiveType()==RrIncentiveAuthorization.Type.MONETARY){if(amount==null)throw new IllegalArgumentException("Monetary fulfillment requires an amount");BigDecimal total=history.stream().map(RrFulfillmentEvent::getFulfilledAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add).add(amount);if(total.compareTo(authorization.getAuthorizedAmount())>0)throw new IllegalArgumentException("Fulfillment exceeds the authorized amount");if(in.status()==RrFulfillmentEvent.Status.FULFILLED&&total.compareTo(authorization.getAuthorizedAmount())!=0)throw new IllegalArgumentException("Final monetary fulfillment must equal the authorized amount");}else if(amount!=null)throw new IllegalArgumentException("Non-monetary fulfillment cannot contain an amount");
  var value=fulfillment.saveAndFlush(new RrFulfillmentEvent(a,authorizationId,in.status(),amount,in.details(),in.evidenceReference(),in.evidenceChecksum(),actor,Instant.now()));record(a,"RECORD_RR_INCENTIVE_FULFILLMENT",value,null,fulfillmentResponse(value),in.details(),c);return response(a,current);
 }
 @Override public AwardResponse recordHap(String a,String id,HapInput in,String actor,String c){var award=leaf(a,id);active(award);var history=hap.findByAgencyIdAndAwardRecordIdOrderByRecordedAt(a,award.getId());var previous=history.isEmpty()?null:history.get(history.size()-1).getStatus();if(!validHap(previous,in.status()))throw new IllegalStateException("Invalid HAP endorsement status transition");var value=hap.saveAndFlush(new RrHapEndorsementEvent(a,award.getId(),in.status(),in.externalReference(),in.details(),actor,Instant.now()));record(a,"RECORD_RR_HAP_ENDORSEMENT",value,null,hapResponse(value),in.details(),c);return response(a,award);}
 @Override @Transactional(readOnly=true) public AnnualRegisterResponse annualRegister(String a,int year){
  if(year<2000||year>2100)throw new IllegalArgumentException("year is outside the supported range");var current=awards.findByAgencyIdOrderByAuthorizedAtDesc(a).stream().filter(x->current(a,x)&&yearOf(a,x)==year).toList();List<AnnualRegisterRow> rows=current.stream().map(x->registerRow(a,x)).toList();BigDecimal authorized=rows.stream().map(AnnualRegisterRow::monetaryAuthorized).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal fulfilledAmount=rows.stream().map(AnnualRegisterRow::monetaryFulfilled).reduce(BigDecimal.ZERO,BigDecimal::add);return new AnnualRegisterResponse(year,rows.stream().filter(x->!x.status().equals("REVOKED")).count(),rows.stream().filter(x->x.status().equals("REVOKED")).count(),authorized,fulfilledAmount,rows);
 }
 private int yearOf(String a,RrAwardRecord x){var date=x.getConferredOn()!=null?x.getConferredOn():lineage(a,x.getRootAwardId()).get(0).getConferredOn();return date.getYear();}
 private AnnualRegisterRow registerRow(String a,RrAwardRecord x){var auths=lineage(a,x.getRootAwardId()).stream().flatMap(y->incentives.findByAgencyIdAndAwardRecordIdOrderByAuthorizedAt(a,y.getId()).stream()).toList();BigDecimal authorized=auths.stream().filter(y->y.getIncentiveType()==RrIncentiveAuthorization.Type.MONETARY).map(RrIncentiveAuthorization::getAuthorizedAmount).reduce(BigDecimal.ZERO,BigDecimal::add);BigDecimal fulfilledAmount=auths.stream().flatMap(y->fulfillment.findByAgencyIdAndAuthorizationIdOrderByRecordedAt(a,y.getId()).stream()).map(RrFulfillmentEvent::getFulfilledAmount).filter(Objects::nonNull).reduce(BigDecimal.ZERO,BigDecimal::add);long nonMon=auths.stream().filter(y->y.getIncentiveType()==RrIncentiveAuthorization.Type.NON_MONETARY).count();long fulfilledCount=auths.stream().filter(y->{var e=fulfillment.findByAgencyIdAndAuthorizationIdOrderByRecordedAt(a,y.getId());return !e.isEmpty()&&e.get(e.size()-1).getStatus()==RrFulfillmentEvent.Status.FULFILLED;}).count();var date=x.getConferredOn()!=null?x.getConferredOn():lineage(a,x.getRootAwardId()).get(0).getConferredOn();return new AnnualRegisterRow(x.getRootAwardId(),x.getAwardCode(),x.getRevisionNo(),x.getNomineeType(),x.getNomineeDisplayName(),x.getCategoryTitle(),date,x.getRecordType()==RrAwardRecord.RecordType.REVOCATION?"REVOKED":"CONFERRED",authorized,fulfilledAmount,nonMon,fulfilledCount);}
 private AwardResponse response(String a,RrAwardRecord x){return new AwardResponse(x.getId(),x.getVersion(),x.getEvaluationCaseId(),x.getNominationId(),x.getCycleId(),x.getCategoryVersionId(),x.getAwardCode(),x.getRevisionNo(),x.getRootAwardId(),x.getSupersedesAwardId(),x.getRecordType().name(),x.getNomineeType(),x.getNomineeDisplayName(),x.getCategoryTitle(),x.getCertificateTitle(),x.getPublicationCitation(),x.getConferredOn(),x.getChangeReason(),x.getAuthorizedBy(),x.getAuthorizedAt(),x.getSourceFingerprint(),current(a,x),x.getRecordType()==RrAwardRecord.RecordType.REVOCATION,incentives.findByAgencyIdAndAwardRecordIdOrderByAuthorizedAt(a,x.getId()).stream().map(y->incentiveResponse(a,y)).toList(),hap.findByAgencyIdAndAwardRecordIdOrderByRecordedAt(a,x.getId()).stream().map(this::hapResponse).toList());}
 private IncentiveResponse incentiveResponse(String a,RrIncentiveAuthorization x){return new IncentiveResponse(x.getId(),x.getIncentiveType().name(),x.getDescription(),x.getAuthorizedAmount(),x.getCurrencyCode(),x.getAuthorizationReference(),x.getAuthorizedBy(),x.getAuthorizedAt(),fulfillment.findByAgencyIdAndAuthorizationIdOrderByRecordedAt(a,x.getId()).stream().map(this::fulfillmentResponse).toList());}
 private FulfillmentResponse fulfillmentResponse(RrFulfillmentEvent x){return new FulfillmentResponse(x.getId(),x.getStatus().name(),x.getFulfilledAmount(),x.getDetails(),x.getEvidenceReference(),x.getEvidenceChecksum(),x.getRecordedBy(),x.getRecordedAt());}
 private HapResponse hapResponse(RrHapEndorsementEvent x){return new HapResponse(x.getId(),x.getStatus().name(),x.getExternalReference(),x.getDetails(),x.getRecordedBy(),x.getRecordedAt());}
 private boolean visible(String a,RrAwardRecord x,String actor,PermissionDataScope scope){if(scope==PermissionDataScope.AGENCY_WIDE)return true;var n=nominations.findByIdAndAgencyId(x.getNominationId(),a).orElse(null);if(n!=null&&(actor.equalsIgnoreCase(n.getNominatorEmployeeNo())||actor.equalsIgnoreCase(Objects.toString(n.getIndividualEmployeeNo(),""))||members.findByAgencyIdAndNominationIdOrderByDisplayOrderAsc(a,n.getId()).stream().anyMatch(m->actor.equalsIgnoreCase(m.getEmployeeNo()))))return true;return assignments.findByAgencyIdAndEvaluationCaseIdOrderByDisplayName(a,x.getEvaluationCaseId()).stream().anyMatch(y->actor.equalsIgnoreCase(y.getEmployeeNo()));}
 private void access(String a,RrAwardRecord x,String actor,PermissionDataScope scope){if(!visible(a,x,actor,scope))throw new AccessDeniedException("Award record is outside the permitted scope");}
 private void validateConferment(String a,String cycleId,LocalDate date){var cycle=cycles.findByIdAndAgencyId(cycleId,a).orElseThrow(()->new ResourceNotFoundException("Award cycle not found"));if(cycle.getConfermentOn()!=null&&!cycle.getConfermentOn().equals(date))throw new IllegalArgumentException("Conferment date must match the frozen award cycle");if(date.isBefore(cycle.getDecisionDueOn()))throw new IllegalArgumentException("Conferment cannot precede the decision due date");}
 private String nominee(String a,RrNomination n){return switch(n.getNomineeType()){case INDIVIDUAL->n.getIndividualName();case ORGANIZATION_UNIT->n.getOrganizationName();case GROUP->n.getGroupName()+" ("+members.findByAgencyIdAndNominationIdOrderByDisplayOrderAsc(a,n.getId()).stream().map(RrNominationMember::getEmployeeName).reduce((l,r)->l+", "+r).orElse("no members")+")";};}
 private RrAwardRecord award(String a,String id){return awards.findByIdAndAgencyId(id,a).orElseThrow(()->new ResourceNotFoundException("Award record not found"));}
 private RrAwardRecord leaf(String a,String id){var x=award(a,id);if(!current(a,x))throw new OptimisticConflictException("Award record has a successor; reload the current revision");return x;}
 private boolean current(String a,RrAwardRecord x){return !awards.existsByAgencyIdAndSupersedesAwardId(a,x.getId());}
 private RrAwardRecord currentAward(String a,String root){var rows=lineage(a,root);return rows.get(rows.size()-1);}
 private List<RrAwardRecord> lineage(String a,String root){var rows=awards.findByAgencyIdAndRootAwardIdOrderByRevisionNo(a,root);if(rows.isEmpty())throw new ResourceNotFoundException("Award lineage not found");return rows;}
 private static void active(RrAwardRecord x){if(x.getRecordType()==RrAwardRecord.RecordType.REVOCATION)throw new IllegalStateException("A revoked award cannot be processed");}
 private static void check(long actual,Long expected){if(expected==null||actual!=expected)throw new OptimisticConflictException("Record changed; reload and retry");}
 private static boolean validHap(RrHapEndorsementEvent.Status from,RrHapEndorsementEvent.Status to){if(from==null)return to==RrHapEndorsementEvent.Status.PREPARED;return switch(from){case PREPARED->to==RrHapEndorsementEvent.Status.ENDORSED||to==RrHapEndorsementEvent.Status.WITHDRAWN;case ENDORSED->to==RrHapEndorsementEvent.Status.SUBMITTED||to==RrHapEndorsementEvent.Status.WITHDRAWN;case SUBMITTED->to==RrHapEndorsementEvent.Status.ACKNOWLEDGED||to==RrHapEndorsementEvent.Status.RETURNED||to==RrHapEndorsementEvent.Status.WITHDRAWN;case RETURNED->to==RrHapEndorsementEvent.Status.PREPARED||to==RrHapEndorsementEvent.Status.WITHDRAWN;case ACKNOWLEDGED,WITHDRAWN->false;};}
 private static String fingerprint(String...values){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(String.join("\u001f",values).getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private void record(String a,String action,com.primehr.rsp.domain.RspAuditedEntity value,Object before,Object after,String reason,String c){audit.record(a,action,value.getClass().getSimpleName(),value.getId(),null,value.getVersion(),before,after,reason,c);}
}
